INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Fecha de inicio de pago de renta', 'A partir del vencimiento del Plazo de Gracia, o bien en la fecha que LA ARRENDATARIA inicie operaciones del NEGOCIO que será instalado en EL LOCAL COMERCIAL.', 'America Gonzalez', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Base Rent', '8', 'Sexta', 'IMPORTE DE LA RENTA DEL LOCAL COMERCIAL', E'- Once the Grace Period ends or when the Tenant starts business operations in the Commercial Space, whichever comes first, the Tenant will pay the Landlord the greater of the following amounts:\n  - $500,000.00 MXN plus applicable VAT (referred to as "Minimum Rent").\n  - 5% of the Tenant''s Monthly Net Income from the Commercial Space, plus applicable VAT (referred to as "Variable Rent").', 'A partir del vencimiento del Plazo de Gracia, o bien en la fecha que LA ARRENDATARIA inicie operaciones del NEGOCIO que será instalado en EL LOCAL COMERCIAL, lo que suceda primero, LA ARRENDATARIA pagará a EL ARRENDADOR, lo que resulte mayor entre las cantidades que se indican a continuación: a) La cantidad de $500,000.00 (QUINIENTOS MIL PESOS 00/100 M.N.) más el I.V.A. correspondiente (en lo sucesivo la "Renta Mínima"); y b) El 5.0% (cinco por ciento) de los Ingresos Netos Mensuales (según dicho término se define más adelante) que perciba LA ARRENDATARIA en EL LOCAL COMERCIAL, más el I.V.A. correspondiente (en lo sucesivo la "Renta Variable").');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Common Area Maintenance Charges', '9', 'Séptima', 'CUOTA DE MANTENIMIENTO', E'- The tenant must pay a monthly maintenance fee to the Américas Xalapa Shopping Center Administration from the contract signing date until they remove all their belongings from the commercial space.\n- The fee amount is determined by the Shopping Center''s Assembly of Co-owners and will be communicated in writing by the administrator.\n- Initially, the fee is 15% of the tenant''s monthly minimum rent.\n- The tenant must also pay any additional fees set by the Assembly of Co-owners, as notified in writing by the administrator.\n- Payment details will be provided in the notification.\n- The tenant must provide the landlord with copies of payment receipts for the maintenance and any additional fees within 10 days after the payment deadline.\n- Failure to provide these receipts can lead to the termination of the contract.', 'A partir de la fecha de firma del presente contrato y hasta la fecha en que LA ARRENDATARIA retire sus bienes completamente de EL LOCAL COMERCIAL, LA ARRENDATARIA se obliga a pagar mensualmente a la Administración del Centro Comercial Américas Xalapa por concepto de cuota de mantenimiento, la cantidad que sea determinada por la Asamblea de Condóminos del Centro Comercial Américas Xalapa y que le haya sido notificada por escrito por parte del administrador del Centro Comercial Américas Xalapa. La cual al inicio de este contrato será la cantidad que resulte de aplicar el 15% (quince por ciento) a la Renta Mínima mensual que LA ARRENDATARIA tenga la obligación de pagar Sin perjuicio de lo anterior, LA ARRENDATARIA se obliga a pagar a la Administración del Centro Comercial Américas Xalapa todas aquellas cuotas extraordinarias que sean determinadas por la Asamblea de Condóminos del Centro Comercial Américas Xalapa, y que le sean notificadas por escrito de manera indubitable por parte del Administrador del Centro Comercial Américas Xalapa. El lugar y forma de pago de los conceptos descritos anteriormente estarán señalados en la notificación a que hacen referencia los párrafos anteriores. Aunado a lo anterior, LA ARRENDATARIA se obliga a entregar a LA ARRENDADORA en un plazo no mayor a 10 (diez) días naturales posteriores a la fecha límite de pago de la cuota mensual de mantenimiento y, en su caso, de las cuotas extraordinarias determinadas por la Asamblea de Condóminos del Centro Comercial Américas Xalapa, copia de los recibos que amparen el pago de los mismos, en el entendido de que e incumplimiento a esta obligación será causal de rescisión del presente contrato.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Key Money', '9', 'Sexta bis', 'DERECHO DE CONTRATO', E'- The tenant must pay the landlord a one-time fee of $5,000,000 plus VAT when signing the contract. This fee is non-refundable.\n- The payment is split into two parts:\n  1. $2,500,000 plus VAT upon signing the contract.\n  2. $2,500,000 plus VAT upon delivery of the commercial space.\n- If the shopping center project is not completed by December 2029, the landlord will refund the contract fee to the tenant.\n- If the size of the commercial space changes, the second payment will be adjusted proportionally.', E'LA ARRENDATARIA se obliga a pagar a EL ARRENDADOR por única vez en la fecha de firma de este Contrato, la cantidad de $5''000,000.00 (CINCO MILLONES DE PESOS 00/100 M.N.) más el I.V.A. correspondiente, por concepto de Derecho de Contrato, cantidad que no se devolverá por ningún motivo. La cantidad antes mencionada la cubrirá LA ARRENDATARIA en 2 (dos) pagos de la siguiente manera: 1) A partir de la fecha de firma del presente contrato, la cantidad de $2,500,000.00 (Dos millones quinientos mil pesos 00/100 M.N.) más el I.V.A. correspondiente 2) A partir de la fecha de entrega de EL LOCAL COMERCIAL, la cantidad de $2,500,00.00 (Dos millones quinientos mil pesos 00/100 M.N.) más el I.V.A. correspondiente.\n\nAdicional a lo anterior las Partes acuerdan que: i) en caso de que el proyecto del Centro Comercial no se lleve a cabo EL ARRENDADOR a más tardar en diciembre de 2029, hará la devolución a LA ARRENDATARIA de la cantidad del Derecho de Contrato que haya depositado; y ii) en caso de que la medida del LOCAL COMERCIAL varíe, se ajustará la cantidad del segundo pago en la misma proporción.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Extension period', '7', 'Cuarta', 'PLAZO', E'- La arrendataria puede extender el contrato por 5 años más.\n- Debe notificar al arrendador al menos 180 días antes.\n- Las condiciones económicas de la extensión se revisarán.\n- Cualquier aumento en la renta no puede ser mayor al 12.5% de la última renta mínima.', 'La ARRENDATARIA tendrá el derecho de prorrogar el presente Contrato por un periodo adicional de cinco (5) años, previa notificación al ARRENDADOR con al menos noventa (180) días de anticipación, para lo cual las partes revisaran bajo qué condiciones económicas se dará dicha prórroga ya que caso de acordar un incremento, este no podrá exceder del 12.5% (doce punto cinco por ciento) de la última Renta Mínima.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Incremento de Renta', '8', 'Sexta', 'IMPORTE DE LA RENTA DEL LOCAL COMERCIAL', E'- "Net Monthly Income" refers to the total income the tenant earns from activities in the commercial space, minus returns, cancellations, taxes, and bank fees.\n- The rent paid by the tenant will be adjusted annually based on the percentage increase in the National Consumer Price Index as published by INEGI.', 'Para efectos de este contrato, se entenderá como Ingresos Netos Mensuales, el importe de los ingresos totales que LA ARRENDATARIA obtenga en el mes inmediato anterior, derivado de las actividades que desarrolle en EL LOCAL COMERCIAL, de acuerdo al Destino que se establece al efecto en la Cláusula Quinta, descontando de éstos el importe correspondiente a devoluciones, cancelaciones, impuestos y comisiones bancarias de las ventas efectuadas. Las Partes convienen en que la RENTA que pagará LA ARRENDATARIA a EL ARRENDADOR, se ajustará anualmente en el mismo porcentaje de incremento que reporte el Índice Nacional de Precios al Consumidor publicado por el INEGI en el Diario Oficial de la Federación, considerando el último período de 12 (doce) meses al del incremento, y así sucesivamente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Late Fees', '10', 'octava', 'FORMA Y LUGAR DE PAGO DE LA RENTA', E'- If the tenant fails to pay rent on time, they will incur a late interest charge.\n- The interest rate will be three times the 28-day Interbank Equilibrium Interest Rate (TIIE) published by the Bank of Mexico.\n- This interest is calculated from the due date until the full payment is made.', 'El incumplimiento por parte de LA ARRENDATARIA en el pago de la RENTA de conformidad a la presente cláusula, causará un interés moratorio equivalente a la tasa de Interés Interbancaria de equilibrio (TIIE) a 28 días, publicada por el Banco de México, multiplicada por 3 (tres), calculados desde la fecha en que debió haber sido pagada, hasta el día en que efectivamente se realice el pago total del adeudo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Parking', '10', 'Novena', 'OBLIGACIONES DEL ARRENDADOR', E'- Si el centro comercial cobra por estacionamiento, las partes decidirán si el arrendador ofrece estacionamiento gratuito para parte del personal de la arrendataria.\n- Otros empleados, clientes, proveedores, directivos o visitantes de la arrendataria deberán pagar las tarifas de estacionamiento vigentes.\n- Se ofrecerá una tarifa preferencial de estacionamiento para los clientes de la arrendataria, no mayor a $10.00 por las primeras 2 horas. Después de 2 horas, se aplicará la tarifa regular.\n- La tarifa preferencial se actualizará cada 24 meses si hay un aumento general en el centro comercial.\n- La arrendataria debe instalar, a su costo, una máquina o sistema de validación de boletos de estacionamiento compatible con el sistema del centro comercial dentro de 60 días después de que se permita el cobro por estacionamiento, previa notificación del arrendador.\n- El arrendador debe cumplir con el número de espacios de estacionamiento requeridos por la ley.', E'En caso de que en el Centro Comercial se cobre cuota por el uso de estacionamiento, en su momento las Partes definirán que EL ARRENDADOR le otorgue pensiones o cortesías para el uso gratuito del área de estacionamiento del Centro Comercial para parte del staff de LA ARRENDATARIA, cortesías que deberán permanecer vigentes, hasta la fecha que en su momento se pacte; las pensiones mencionadas con anterioridad, cualquiera de los demás empleados, clientes, proveedores, directivos o visitantes de LA ARRENDATARIA, ARRENDATARIA, deberán pagar las cuotas de estacionamiento vigentes que determine la Administración del Centro Comercial, para los demás visitantes que acudan al mismo.\nEn caso de que se cobre cuota por el uso de estacionamiento de conformidad con la legislación local, y adicional a lo indicado en el punto anterior, otorgar a LA ARRENDATARIA una tarifa preferencial para sus clientes, respecto a la cuota de estacionamiento vigente que se cobre en el Centro Comercial. Dicha cuota preferencial de estacionamiento no podrá ser mayor a $10.00 (Diez Pesos 00/100 M.N.) por las primeras 2 (dos) horas que permanezcan en el estacionamiento; una vez transcurridas las primeras 2 (dos) horas, los clientes de LA ARRENDATARIA deberán pagar la tarifa vigente que aplique. Dicho pago se deberá de actualizarse una vez que se implemente el cobro cada 24 (veinticuatro) meses, siempre y cuando el incremento se realice para el Centro Comercial.\nA ARRENDATARIA quedará obligada a que a más tardar en un plazo de 60 (sesenta) días posteriores a que de acuerdo con la legislación local se permita el cobro por el uso del Estacionamiento del Centro Comercial y previa notificación por parte de EL ARRENDADOR, deberá instalar por su cuenta y su costo, una máquina Validadora de Boletos de estacionamiento, o bien un sistema de validación de boletos que sea compatible con el sistema de cobro de cuotas de estacionamiento que se encuentre operando en el Centro Comercial, el cual, previo a su instalación, deberá ser validado y autorizado por EL ARRENDADOR. Asimismo, EL ARRENDADOR, se obliga a contar con el número de cajones exigidos por la legislación correspondiente.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('04be1473-b23d-497c-92d1-364b781717eb', 'Período para obtener licencia y permisos', '13', 'Décima primera', 'DERECHOS DE LA ARRENDATARIA', E'- If within 120 days from the delivery of the commercial space, the necessary permits, licenses, or services are not provided to the tenant, the tenant can choose to:\n  - Terminate the contract without any penalty, and the landlord must refund any payments made by the tenant.\n  - Agree to a new 120-day period to obtain the necessary permits and licenses.\n\n- These options are valid if:\n  - The tenant proves they have made efforts to obtain the permits and services.\n  - The failure to obtain them is not the tenant''s fault.\n  - After the chosen period ends, the landlord has 60 days to try to obtain the required permits and services.', E'Si en un plazo de 120 (ciento veinte) días naturales, contados a partir de entrega del LOCAL COMERCIAL a LA ARRENDATARIA, las autoridades y/o dependencias públicas y/o compañías correspondientes, no le han proporcionado los permisos y licencias y/o servicios con las especificaciones requeridas por LA ARRENDATARIA, la misma podrá, a su elección realizar las siguientes opciones:\nA) Dar por terminado el presente Contrato, sin responsabilidad alguna para ninguna de las Partes, quedando obligado EL ARRENDADOR a devolver a LA ARRENDATARIA las cantidades que esta última le haya entregado a EL ARRENDADOR de conformidad al presente Contrato.\n\nB) Acordar un nuevo plazo de 120 (ciento veinte) días naturales, para la obtención de los permisos licencias correspondientes. Lo indicado en el inciso a y b anterior, operará siempre y cuando: i) LA ARRENDATARIA demuestre fehacientemente a EL ARRENDADOR que realizó las gestiones necesarias ante las autoridades correspondientes para la obtención de sus permisos, licencias y/o servicios; ii) que la no obtención de dichos permisos, licencias y/o servicios, no se deriva de una causa imputable a LA ARRENDATARIA, ya que de lo contrario LA ARRENDATARIA estará en incumplimiento de esta obligación; y iii) qué una vez que LA ARRENDATARIA, haya agotado cualquiera de los plazos previstos en los incisos a y b anteriores, según el que haya elegido y le haya notificado por escrito a EL ARRENDADOR, este último agote un plazo máximo de 60 (sesenta) días naturales contados a partir de dicha notificación, para tratar de obtener los permisos y licencias y/o servicios con las especificaciones requeridas por LA ARRENDATARIA para su operación.');
