ining_rent_liability_over_time":64165}'::jsonb);
INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', '4aafc3f8-033e-46cd-bb2e-bde9356f2d34', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Escobedo Sublease: Tiendas Soriana, S.A. De C.V. (11/01/2026 - 10/31/2036)', NULL, true, 'vencido', 'Lease', NULL, '2026-11-01', '2026-05-04', '2036-10-31', '2041-10-31', false, 1, NULL, 1, NULL, NULL, '2036-09-01', 'Send Notice to Renew', 119, 'Tiendas Soriana, S.A. De C.V.', NULL, NULL, '3102 Avenida Alejandro De Rodas', 'A', 'Monterrey', 'MX-NLE', '64610', 'MX', 'Marcela Pérez Olivas', '818-329-9048', NULL, 180, 'percent', NULL, NULL, NULL, NULL, 3870816, false, '{"lease_most_recent_note":"Yes","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1}'::jsonb);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Domicilio del Contrato', 'Av. Parque Industrial número 201 Colonia Los Girasoles 2° Sector C.P. 66050 en Escobedo N.L.', 'Paola Guerrero', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Fecha de entrega del inmueble', '4 de mayo de 2026', 'Paola Guerrero', NULL);
INSERT INTO lease_notes (lease_id, titulo, nota, autor_nombre, fecha_nota) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Fecha de Firma del Contrato', '4 de mayo 2026', 'Paola Guerrero', NULL);
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Renewal Option', '2', 'Segunda', 'VIGENCIA', E'- The subtenant can request a 5-year extension by notifying the sublandlord 60 days before the current lease ends.\n- This extension is mandatory for the sublandlord but optional for the subtenant.\n- The terms of the extension, including rent, must be mutually agreed upon.\n- Rent for the extension cannot increase more than 10% from the current rent.\n- Negotiation timelines outlined in the clause must be followed.', 'EL SUBARRENDATARIO tendrá la opción de solicitar con 60 (sesenta) días naturales de anticipación a la fecha en que finalice la vigencia inicial y mediante notificación formal al domicilio de LA SUBARRENDADORA, 1 (una) prorroga de 5 (cinco) años, plazo que será forzoso para LA SUBARRENDADORA y voluntarios para EL SUBARRENDATARIO. Las condiciones que serán aplicables a dicha prórroga deberá de ser negociadas de común acuerdo entre las Partes, fijando el precio de renta aplicable para dicha prórroga conforme al valor de mercado actualizado, cuyo incremento no deberá de sobrepasar un 10% (diez por ciento) de la última renta vigente y tomando en consideración los plazos para negociar establecidos en la presente cláusula.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Common Area Maintenance Charges', '4', 'Cuarta', 'CONTRAPRESTACIÓN', E'- The subtenant must pay a maintenance fee equal to 10% of the current monthly rent.\n- This fee is called the "Maintenance Fee."\n- Payment starts either when the grace period ends or when the business begins operations in the commercial area, whichever comes first.\n- The fee will include the applicable value-added tax or any tax that may replace it in the future.', 'Adicionalmente EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% (diez por ciento) de la renta mensual vigente (en lo sucesivo la "Cuota de Mantenimiento"), dicha cantidad se comenzará a pagar a partir de lo que suceda primero, ya sea el vencimiento del periodo de gracia o del inicio de operaciones del negocio que operará en EL ÁREA COMERCIAL, en el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Incremento de Renta', '5', 'Quinta', 'AUMENTO DE RENTA', E'- The monthly rent for the sublease of the commercial area will increase annually.\n- The increase will be based on the rise in the National Consumer Price Index published by INEGI or any index that replaces it for measuring inflation in Mexico.\n- The annual increase cannot exceed 8% of the current rent amount.', 'El importe de la contraprestación mensual por el subarrendamiento de EL ÁREA COMERCIAL se incrementará anualmente, a partir del primer aniversario de la fecha de apertura al público, en la misma proporción en que aumente el Índice Nacional de Precios al Consumidor que publique el INEGI (o el índice que lo sustituyere para medir la inflación en los Estados Unidos Mexicanos), en la inteligencia de que dichos aumentos anuales no podrán ser mayor a un 8% (ocho por ciento) del valor de la contraprestación vigente que opere en dicho periodo.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('2393d072-0efe-4429-9565-af3f64f9c3e6', 'Hours of Operation', '9', 'Séptima', 'DEL GIRO Y HORARIO', E'- The business can operate from 5:00 AM to 11:00 PM, or according to local regulations.\n- To operate 24/7 all year, except on December 25 and January 1 (closed), and with reduced hours on December 24 and 31, a proper permit from the authorities is required.', 'Las Partes acuerdan que el Giro Comercial podrá operar de las 05:00 a 23:00 horas o conforme señale la normatividad aplicable en el municipio donde se encuentra EL ÁREA COMERCIAL, por lo que si desea operar las 24 (veinticuatro) horas del día, los 7 (siete) días de la semana, y durante todo el año, excepto el 25 (veinticinco) de diciembre y 1 (primero) de enero, en que permanecerá cerrado, y los días 24 (veinticuatro) y 31 (treinta y uno) de diciembre podrá operar con horario reducido, deberá de contar con el permiso debidamente expedido por la autoridad competente.');
